-- Stop-to-stop fares from Jack's sheet (fares to fill v1, 5 Oct 2026: Margaritaville and Carnival).
-- Per person, before VAT. Generated by scripts/import-fares.py.

on conflict (slug) do update set
  price_cents = excluded.price_cents, round_trip_cents = excluded.round_trip_cents,
  from_point = excluded.from_point, to_point = excluded.to_point, is_active = true;
